	public void CallerPoliciesRetainPinnedNativeSpansCapturesAndLabels( string hex, string subjectHex, int policy, int mode, string spans, string mark ) {
		var source = Convert.FromHexString( hex );
		var subject = Convert.FromHexString( subjectHex );
		var reference = Reference( source, policy, mode );
		AssertLiteral( reference, subject, 0, spans, mark );
		Compare( reference, subject, 0, Compile( source, Options( policy, mode ) ).Match( subject ), "caller case policy" );
	}

