	[InlineData( "282A434153454C4553535F5245535452494354582949", 3, 2048, 204, 0, "InvalidSyntax", 0, "Turkish" )]
	[InlineData( "282A434153454C4553535F5245535452494354582949", 3, 2049, 206, 0, "InvalidSyntax", 0, "Turkish" )]
	[InlineData( "28", 2, 0, 204, 0, "InvalidSyntax", 0, "Turkish" )]
	[InlineData( "28", 2, 2, 205, 0, "InvalidSyntax", 0, "Turkish" )]
	[InlineData( "28", 2, 1, 114, 1, "InvalidSyntax", 0, "" )]
	[InlineData( "28", 2, 7, 114, 1, "InvalidSyntax", 0, "" )]
	[InlineData( "28", 2, 2048, 204, 0, "InvalidSyntax", 0, "Turkish" )]
	[InlineData( "28", 2, 2049, 114, 1, "InvalidSyntax", 0, "" )]
	[InlineData( "28", 3, 0, 204, 0, "InvalidSyntax", 0, "Turkish" )]
	[InlineData( "28", 3, 2, 205, 0, "InvalidSyntax", 0, "Turkish" )]
	[InlineData( "28", 3, 1, 206, 0, "InvalidSyntax", 0, "Turkish" )]
	[InlineData( "28", 3, 7, 206, 0, "InvalidSyntax", 0, "Turkish" )]
	[InlineData( "28", 3, 2048, 204, 0, "InvalidSyntax", 0, "Turkish" )]
	[InlineData( "28", 3, 2049, 206, 0, "InvalidSyntax", 0, "Turkish" )]
	public void CallerAndSourceValidationRetainNativePriorityAndOffsets( string hex, int policy, int mode, int nativeCode, int nativeOffset, string code, int offset, string family ) {
		var source = Convert.FromHexString( hex );
		if ( nativeCode == 0 ) { _ = Reference( source, policy, mode ); }
		else {
			var native = Assert.Throws<PcrePatternException>( () => Reference( source, policy, mode ) );
			Assert.Equal( nativeCode, (int)native.ErrorCode );
			Assert.EndsWith( $" at offset {nativeOffset}.", native.Message );
		}
		var actual = PcreByteCompiler.Compile( source, Options( policy, mode ) );
		Assert.Equal( Enum.Parse<PcreByteDiagnosticCode>( code ), actual.Diagnostic?.Code );
		Assert.Equal( offset, actual.Diagnostic?.ByteOffset );
		Assert.Null( actual.Pattern );
		if ( family.Length != 0 ) { Assert.Contains( family, actual.Diagnostic!.Message ); }
	}

	[Theory]
	[InlineData( 1, 9, "73,74,75,105,106,107" )]
	[InlineData( 2, 9, "73,74,75,106,107,305,8490" )]
	[InlineData( 1, 8, "73,74,75,105,106,107" )]
	public void CompleteSelectedClassMembershipRetainsNativePolicy( int policy, int mode, string members ) {
		var source = "(?i)[I-K]"u8.ToArray();
		var reference = Reference( source, policy, mode );
		var values = Enumerable.Range( 0, 256 ).Concat( ( mode & 1 ) != 0 ? new[] { 304, 305, 383, 8490 } : Array.Empty<int>() ).ToArray();
		var subjects = values.Select( value => ( mode & 1 ) != 0 ? Encoding.UTF8.GetBytes( char.ConvertFromUtf32( value ) ) : new[] { (byte)value } ).ToArray();
		var expected = members.Split( ',' ).Select( Int32.Parse ).ToHashSet();
		for ( var index = 0; index < values.Length; index++ ) {
			AssertLiteral( reference, subjects[index], 0, expected.Contains( values[index] ) ? $"0:{subjects[index].Length}" : "", "" );
		}
		var compiled = Compile( source, Options( policy, mode ) );
		foreach ( var subject in subjects ) { Compare( reference, subject, 0, compiled.Match( subject ), "complete membership" ); }
	}

	[Theory]
	[InlineData( "(*LF)", 1 )]
	[InlineData( "(*LF)", 2 )]
	[InlineData( "(*ANYCRLF)", 1 )]
	[InlineData( "(*ANYCRLF)", 2 )]
	[InlineData( "(*CR)", 1 )]
	[InlineData( "(*CR)", 2 )]
	[InlineData( "(*NUL)", 1 )]
	[InlineData( "(*NUL)", 2 )]
	[InlineData( "(*CRLF)", 1 )]
	[InlineData( "(*CRLF)", 2 )]
	[InlineData( "(*ANY)", 1 )]
	[InlineData( "(*ANY)", 2 )]
	public void EveryOffsetRetainsNewlineAndMalformedFragmentPolicies( string newline, int policy ) {
		var bodies = new[] { "I(A)", "[I-K](A)", @"(?i)(K)\1", "(?i)(?<=I)A", "(?i)(?m)^(*MARK:K)[I-K]A", "(?^i:I)(A)" };
		var sources = bodies.Select( body => Encoding.ASCII.GetBytes( String.Concat( newline, body ) ) ).ToArray();
		var references = sources.Select( source => Reference( source, policy, 15 ) ).ToArray();
		for ( var index = 0; index < sources.Length; index++ ) {
			var compiled = Compile( sources[index], Options( policy, 15 ) );
			foreach ( var hex in new[] { "", "4941", "6941", "C4B041", "C4B141", "4B4B", "4BE284AA", "0D0A4941", "E280A8C4B141", "FF4941", "EDA0804941", "004941" } ) {
				var subject = Convert.FromHexString( hex );
				for ( var offset = 0; offset <= subject.Length; offset++ ) {
					Compare( references[index], subject, offset, compiled.Match( subject, offset ), $"{newline}/{index}/{hex}/{offset}/{policy}" );
				}
			}
		}
	}

	[Theory]
	[InlineData( 1, "(?i)(K|KK)+B", "KKKB", "3:3,4:1" )]
	[InlineData( 2, "(?i)(I|II)+B", "IıIB", "0:5,3:1" )]
	public void CallerAndPrefixPoliciesHaveIdenticalWorkAndCancellation( int policy, string body, string text, string spans ) {
		var source = Encoding.UTF8.GetBytes( body );
		var canonical = Encoding.UTF8.GetBytes( String.Concat( policy == 1 ? "(*CASELESS_RESTRICT)" : "(*TURKISH_CASING)", body ) );
		var subject = Encoding.UTF8.GetBytes( text );
		var reference = Reference( source, policy, 1 );
		var canonicalReference = Reference( canonical, 0, 1 );
		AssertLiteral( reference, subject, 0, spans, "" );
		AssertLiteral( canonicalReference, subject, 0, spans, "" );
		var callerSteps = new List<int>();
		var prefixSteps = new List<int>();
		var options = Options( policy, 1 ) with { WorkObserver = callerSteps.Add };
		Compare( reference, subject, 0, Compile( source, options ).Match( subject ), "caller work" );
		Compare( canonicalReference, subject, 0, Compile( canonical, Options( 0, 1 ) with { WorkObserver = prefixSteps.Add } ).Match( subject ), "prefix work" );
		Assert.Equal( prefixSteps, callerSteps );
		Assert.Equal( Enumerable.Range( 1, callerSteps.Count ), callerSteps );
		Assert.True( callerSteps.Count > 2 );
		var limited = Compile( source, options with { MatchWorkLimit = callerSteps.Count - 1 } ).Match( subject );
		Assert.Equal( PcreByteDiagnosticCode.MatchWorkLimitExceeded, limited.Diagnostic?.Code );
		Assert.Null( limited.Match );
		using var cancellation = new CancellationTokenSource();
		var compiled = Compile( source, options with { WorkObserver = count => { if ( count == 2 ) { cancellation.Cancel(); } } } );
		Assert.Throws<OperationCanceledException>( () => compiled.Match( subject, 0, cancellation.Token ) );
		Assert.Throws<OperationCanceledException>( () => PcreByteCompiler.Compile( source, options, cancellation.Token ) );
		var invalidWork = PcreByteCompiler.Compile( "("u8.ToArray(), Options( 3, 0 ) with { MatchWorkLimit = 0 } );
		Assert.Equal( PcreByteDiagnosticCode.InvalidWorkLimit, invalidWork.Diagnostic?.Code );
	}

	[Theory]
	[InlineData( 1, "KK", "" )]
	[InlineData( 2, "Iı", "0:3,0:1" )]
	public void CompiledCasePoliciesOwnSourceOptionsAndSuccessfulLabels( int policy, string text, string spans ) {
		var source = Encoding.ASCII.GetBytes( @"(?i)(K|I)(*MARK:K)\1" );
		var subject = Encoding.UTF8.GetBytes( text );
		var reference = Reference( source, policy, 1 );
		AssertLiteral( reference, subject, 0, spans, "4B" );
		AssertLiteral( reference, "KK"u8.ToArray(), 0, "0:2,0:1", "4B" );
		var options = Options( policy, 1 );
		var compiled = Compile( source, options );
		Array.Fill( source, (byte)'x' );
		typeof( PcreByteOptions ).GetProperty( "CaselessRestricted" )?.SetValue( options, false );
		typeof( PcreByteOptions ).GetProperty( "TurkishCasing" )?.SetValue( options, false );
		Compare( reference, subject, 0, compiled.Match( subject ), "owned caller policy" );
		Compare( reference, "KK"u8.ToArray(), 0, compiled.Match( "KK"u8.ToArray() ), "owned label data" );
	}

	[Theory]
	[InlineData( 1, "i", "0:1" )]
	[InlineData( 2, "ı", "0:2" )]
	public void CallerPoliciesRetainCaptureDepthAndExpansionCeilings( int policy, string text, string span ) {
		var patterns = new[] {
			String.Concat( String.Concat( Enumerable.Repeat( "()", 256 ) ), "(?i)I" ),
			String.Concat( String.Concat( Enumerable.Repeat( "()", 257 ) ), "(?i)I" ),
			String.Concat( String.Concat( Enumerable.Repeat( "(?:", 257 ) ), "(?i)I", new string( ')', 257 ) ), "(?i)I{4096}"
		};
		var references = patterns.Select( pattern => Reference( Encoding.ASCII.GetBytes( pattern ), policy, 1 ) ).ToArray();
		var subject = Encoding.UTF8.GetBytes( text );
		AssertLiteral( references[0], subject, 0, String.Concat( span, ",", String.Join( ",", Enumerable.Repeat( "0:0", 256 ) ) ), "" );
		Compare( references[0], subject, 0, Compile( Encoding.ASCII.GetBytes( patterns[0] ), Options( policy, 1 ) ).Match( subject ), "capture capacity" );
		var codes = new[] { PcreByteDiagnosticCode.PatternCaptureLimitExceeded, PcreByteDiagnosticCode.PatternDepthLimitExceeded, PcreByteDiagnosticCode.PatternRepeatLimitExceeded };
		for ( var index = 1; index < patterns.Length; index++ ) {
			var actual = PcreByteCompiler.Compile( Encoding.ASCII.GetBytes( patterns[index] ), Options( policy, 1 ) );
			Assert.Equal( codes[index - 1], actual.Diagnostic?.Code );
			Assert.Null( actual.Pattern );
		}
	}

	private static PcreByteOptions Options( int policy, int mode ) {
		var options = new PcreByteOptions { Utf8 = ( mode & 1 ) != 0, Ucp = ( mode & 2 ) != 0, MatchInvalidUtf = ( mode & 4 ) != 0,
			Caseless = ( mode & 8 ) != 0, AltExtendedClass = ( mode & 16 ) != 0, MatchWord = ( mode & 32 ) != 0, MatchLine = ( mode & 64 ) != 0,
			NeverUtf = ( mode & 512 ) != 0, NeverUcp = ( mode & 1024 ) != 0, NeverCallout = ( mode & 2048 ) != 0 };
		// Keep tests-only RED executable before the two caller options exist.
		if ( ( policy & 1 ) != 0 ) { typeof( PcreByteOptions ).GetProperty( "CaselessRestricted" )?.SetValue( options, true ); }
		if ( ( policy & 2 ) != 0 ) { typeof( PcreByteOptions ).GetProperty( "TurkishCasing" )?.SetValue( options, true ); }
		return options;
	}
	private static PcreRegex8Bit Reference( byte[] source, int policy, int mode ) => new(
		source, Encoding.UTF8, new PcreRegexSettings {
			Options = PcreOptions.Compiled | (PcreOptions)( ( ( mode & 1 ) != 0 ? 0x80000u : 0u ) | ( ( mode & 2 ) != 0 ? 0x20000u : 0u )
				| ( ( mode & 4 ) != 0 ? 0x4000000u : 0u ) | ( ( mode & 8 ) != 0 ? 8u : 0u ) | ( ( mode & 16 ) != 0 ? 0x8000000u : 0u )
				| ( ( mode & 512 ) != 0 ? 0x1000u : 0u ) | ( ( mode & 1024 ) != 0 ? 0x800u : 0u ) ),
			ExtraCompileOptions = (PcreExtraCompileOptions)( ( ( policy & 1 ) != 0 ? 0x80 : 0 ) | ( ( policy & 2 ) != 0 ? 0x10000 : 0 )
				| ( ( mode & 32 ) != 0 ? 4 : 0 ) | ( ( mode & 64 ) != 0 ? 8 : 0 ) | ( ( mode & 2048 ) != 0 ? 0x8000 : 0 ) ), ParensLimit = 512
		} );
	private static PcreCompiledBytePattern Compile( byte[] source, PcreByteOptions options ) {
		var actual = PcreByteCompiler.Compile( source, options );
		Assert.True( actual.IsSuccess, $"{Encoding.UTF8.GetString( source )}: {actual.Diagnostic?.Message}" );
		return Assert.IsType<PcreCompiledBytePattern>( actual.Pattern );
	}
	private static void AssertLiteral( PcreRegex8Bit reference, byte[] subject, int offset, string spans, string mark ) {
		var match = reference.Match( subject, offset );
		Assert.Equal( spans.Length > 0, match.Success );
		if ( !match.Success ) { return; }
		Assert.Equal( mark, Convert.ToHexString( match.Mark.ToArray() ) );
		var groups = spans.Split( ',' );
		Assert.Equal( groups.Length, match.Groups.Count );
		for ( var group = 0; group < groups.Length; group++ ) {
			var capture = match.Groups[group];
			Assert.Equal( groups[group], capture.Success ? $"{capture.Index}:{capture.Length}" : "-" );
		}
	}
	private static void Compare( PcreRegex8Bit reference, byte[] subject, int offset, PcreByteMatchResult actual, string context ) {
		var expected = reference.Match( subject, offset );
		Assert.True( actual.IsSuccess, $"{context}: {actual.Diagnostic?.Message}" );
		Assert.True( ( expected.Success ? expected.Index : -1 ) == ( actual.Match?.ByteIndex ?? -1 ), context );
		if ( !expected.Success ) { return; }
		Assert.Equal( expected.Length, actual.Match!.ByteLength );
		Assert.Equal( expected.Mark.ToArray(), actual.Match.MarkName.ToArray() );
		Assert.Equal( expected.Groups.Count, actual.Match.Captures.Count );
		for ( var group = 0; group < expected.Groups.Count; group++ ) {
			var capture = expected.Groups[group];
			Assert.Equal( capture.Success ? new PcreByteCapture( capture.Index, capture.Length ) : null, actual.Match.Captures[group] );
		}
	}
}
